function operIcon(k){const o=OPER_IC[k];return `<svg viewBox="${o.vb}" width="20" height="20" aria-hidden="true" ${o.rot?'style="transform:rotate(-90deg)"':''}>${o.d.map(d=>`<path d="${d}" fill="#006DFF" ${o.ev?'fill-rule="evenodd" clip-rule="evenodd"':''}/>`).join('')}</svg>`}
const OPER_MAIN=[['bizum','Enviar Bizum','bzf-start'],['enviar','Enviar dinero','journey-transfer'],['sacar','Sacar dinero','oper-na'],['limites','Límites de tarjeta','home-limits'],['impuestos','Pagar impuestos','oper-na'],['domic','Consultar domiciliaciones','journey-payments'],['cert','Solicitar certificado','oper-na'],['bloquear','Bloquear tarjeta','detail-card']];
