function operCell([i,t,a]){return `<button class="oper-cell" data-action="${a}"><span class="oper-circle">${operIcon(i)}</span><span class="oper-label">${t}</span></button>`}
function operarSheet(){return `<div class="oper-layer" data-oper><button class="oper-scrim" data-action="oper-close" aria-label="Cerrar"></button><section class="oper-sheet" role="dialog" aria-label="Operar"><div class="oper-head"><h2>Principales operativas</h2><button class="oper-all" data-action="nav-operar-all">Ver todas</button></div><div class="oper-grid">${OPER_MAIN.map(operCell).join('')}</div><div class="oper-head oper-head2"><h2>¿Te podemos ayudar?</h2></div><div class="oper-grid">${OPER_HELP.map(operCell).join('')}</div></section></div>`}
function operarSync(){const ph=root.querySelector('.phone');if(!ph)return;const has=ph.querySelector('[data-oper]');const nv=ph.querySelector('.bottomnav');if(OPER&&nv&&!has)ph.insertAdjacentHTML('beforeend',operarSheet());if(!OPER&&has)has.remove();const b=ph.querySelector('.nav-operar');if(b){b.classList.toggle('is-open',OPER);b.setAttribute('aria-label',OPER?'Cerrar':'Operar');b.setAttribute('aria-expanded',String(OPER))}}
