function bzfBlank(){return {phone:'',name:'',amount:'',concept:'',touched:false,sent:null}}
function bzf(){if(!state.bzf)state.bzf=bzfBlank();return state.bzf}
function bzfDigits(){return String(bzf().phone).replace(/\D/g,'').replace(/^34(?=\d{9}$)/,'')}
function bzfLookup(){const d=bzfDigits(),valid=/^[67]\d{8}$/.test(d),c=bzfAgenda().find(x=>x.phone===d);return {d,valid,contact:c,formatted:valid?fmtPhone(d):bzf().phone}}
function bzfAmt(){const n=parseAmount(bzf().amount);return Number.isFinite(n)?Math.round(n*100)/100:0}
function bzfName(){const l=bzfLookup();if(l.contact)return l.contact.name;const n=String(bzf().name||'').trim();return n&&!/^\d/.test(n)?n:''}
function bzfConcept(){return String(bzf().concept||'').trim()||'Envío Bizum'}
function bzfErrors(){const f=bzf(),l=bzfLookup(),a=bzfAmt(),bal=money().online;return {phone:f.touched&&!l.valid?'Introduce un móvil válido de 9 dígitos.':'',amount:f.touched&&a<=0?'Introduce un importe mayor que 0,00 €.':a>bal?`Supera tu saldo disponible (${fmt(bal)}).`:a>BZF_MAX?`El límite por operación en Bizum es de ${fmt(BZF_MAX).replace(',00','')}.`:''}}
function bzfOk(){const l=bzfLookup(),a=bzfAmt();return l.valid&&a>0&&a<=money().online&&a<=BZF_MAX}
function bzfStepper(n){return `<div class="bzf-stepper" aria-label="Paso ${n} de 2"><span class="${n>=1?'on':''}">1</span><i></i><span class="${n>=2?'on':''}">2</span><em>${n===1?'Datos':'Revisión'}</em></div>`}
function bzfForm(){const f=bzf(),l=bzfLookup(),er=bzfErrors(),nm=bzfName();return `${headerBack('Enviar Bizum')}<main class="main bzf-main" id="scroller"><div class="bzf-wrap"><section class="bzf-card"><div class="bzf-top">${bzfStepper(1)}<span class="bzf-badge">${BZF_IC}</span></div><div><h2 class="bzf-h">Enviar un Bizum</h2><p class="bzf-sub">Indica el móvil de destino y el importe.</p></div>
<div class="bzf-field ${er.phone?'has-error':''}"><label for="bzf-phone">Móvil de destino</label><div class="bzf-row"><div class="bzf-input"><input id="bzf-phone" name="bzfPhone" inputmode="tel" autocomplete="off" placeholder="600 000 000" value="${esc(f.phone)}"><span class="bzf-suffix bzf-bz" ${l.valid?'':'hidden'}>${BZF_IC}</span></div><button class="bzf-side" data-action="bzf-agenda">${icon('user',18)}<span>Agenda</span></button></div><div class="bzf-hint" id="bzf-phone-hint">${er.phone?esc(er.phone):nm?`<strong>${esc(nm)}</strong>`:''}</div></div>
<div class="bzf-field ${er.amount?'has-error':''}"><label for="bzf-amount">Importe</label><div class="bzf-input"><input id="bzf-amount" name="bzfAmount" inputmode="decimal" autocomplete="off" placeholder="0,00" value="${esc(f.amount)}"><span class="bzf-suffix">€</span></div><div class="bzf-hint" id="bzf-amount-hint">${esc(er.amount)}</div></div>
<div class="bzf-field"><label for="bzf-concept">Concepto <small>(opcional)</small></label><div class="bzf-input"><input id="bzf-concept" name="bzfConcept" autocomplete="off" maxlength="35" placeholder="Envío Bizum" value="${esc(f.concept)}"></div></div></section>
<button class="button-primary bzf-cta" data-action="bzf-review">Enviar Bizum ${icon('right',17)}</button></div></main>`}
function bzfReview(){const l=bzfLookup(),a=bzfAmt(),nm=bzfName();return `${headerBack('Enviar Bizum')}<main class="main bzf-main" id="scroller"><div class="bzf-wrap"><section class="bzf-card"><div class="bzf-top">${bzfStepper(2)}<span class="bzf-tag">Pendiente de firma</span></div><div><h2 class="bzf-h">Revisa y firma el Bizum</h2><p class="bzf-sub">Comprueba los datos antes de firmar la operación.</p></div><div class="bzf-panel"><div class="bzf-hero"><small>Importe a enviar</small><strong>${state.balanceVisible?fmt(a):'•••• €'}</strong></div><div class="bzf-prow"><span>Destinatario</span><span class="bzf-pval"><strong>${esc(nm||l.formatted)}</strong><small><span class="bzf-bz">${BZF_IC}</span>${esc(l.formatted)}</small></span></div><div class="bzf-prow"><span>Concepto</span><span class="bzf-pval">${esc(bzfConcept())}</span></div></div></section>
<button class="button-primary bzf-cta" data-action="bzf-sign">Confirmar envío</button><button class="button-secondary" data-action="bzf-edit">Editar datos</button></div></main>`}
function bzfDone(){const s=bzf().sent;if(!s)return bzfForm();const ini=s.name.replace(/[^A-Za-zÁÉÍÓÚÑáéíóúñ ]/g,'').split(' ').filter(Boolean).slice(0,2).map(w=>w[0]).join('').toUpperCase()||'BZ';return `${headerBack('Enviar Bizum')}<main class="main bzf-main" id="scroller"><div class="bzf-wrap"><section class="bzf-card bzf-sent"><div class="bzf-avatar"><span>${esc(ini)}</span><i>${icon('check',13)}</i></div><span class="bzf-tag ok">Bizum enviado</span><div class="bzf-sent-amt">${fmt(s.amount)}</div><div class="bzf-sent-to">a <strong>${esc(s.name)}</strong></div><div class="bzf-sent-ph"><span class="bzf-bz">${BZF_IC}</span>${esc(s.phone)}</div><div class="bzf-prow"><span>Concepto</span><span class="bzf-pval">${esc(s.concept)}</span></div><div class="bzf-prow"><span>Referencia</span><span class="bzf-pval">${esc(s.ref)}</span></div></section>
<button class="button-primary bzf-cta" data-action="move-open-bz:last">Ver movimiento</button><button class="button-secondary" data-action="bzf-again">Hacer otro Bizum</button><button class="bzf-tertiary" data-action="nav-home">Ir a Inicio</button></div></main>`}
const BZF_SCREENS={move:()=>movePage(),bzf:bzfForm,'bzf-review':bzfReview,'bzf-done':bzfDone};
function bzfLive(){const l=bzfLookup(),nm=bzfName(),er=bzfErrors();const bz=root.querySelector('.bzf-input .bzf-bz');if(bz)bz.hidden=!l.valid;const h=root.querySelector('#bzf-phone-hint');if(h){const msg=er.phone&&!l.valid?esc(er.phone):nm?`<strong>${esc(nm)}</strong>`:'';h.innerHTML=msg;h.closest('.bzf-field').classList.toggle('has-error',!!(er.phone&&!l.valid));}const ah=root.querySelector('#bzf-amount-hint');if(ah){ah.textContent=er.amount;ah.closest('.bzf-field').classList.toggle('has-error',!!er.amount);}}
// Agenda
function bzfAgendaHtml(q=''){const n=s=>s.normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase(),qq=n(q.trim()),dq=q.replace(/\D/g,'');const list=bzfAgenda().filter(c=>!qq||n(c.name+' '+c.sub).includes(qq)||(dq&&c.phone.includes(dq)));return list.length?list.map(c=>`<button class="bzf-contact" data-action="bzf-pick-${c.phone}"><span class="bzf-cav">${esc(c.name.split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase())}</span><span class="bzf-cname">${esc(c.name)}<small>${fmtPhone(c.phone)} · ${esc(c.sub)}</small></span><span class="bzf-bz">${BZF_IC}</span></button>`).join(''):'<p class="bzf-empty">No hay contactos con ese nombre.</p>'}
function bzfAgendaSync(){const ph=root.querySelector('.phone');if(!ph)return;const has=ph.querySelector('[data-bzf-agenda]');if(BZF_AGENDA_OPEN&&!has){ph.insertAdjacentHTML('beforeend',`<div class="bzf-agenda" data-bzf-agenda role="dialog" aria-modal="true" aria-label="Agenda de contactos Bizum"><header class="bzf-ag-head"><button class="iconbtn" data-action="bzf-agenda-close" aria-label="Cerrar agenda"><span class="bzf-x"></span></button><strong>Agenda de contactos</strong><span class="bar-spacer"></span></header><div class="bzf-ag-search"><input name="bzfSearch" type="search" placeholder="Buscar por nombre o teléfono" aria-label="Buscar contacto por nombre o teléfono"></div><div class="bzf-ag-list" id="bzf-ag-list">${bzfAgendaHtml()}</div></div>`);}if(!BZF_AGENDA_OPEN&&has)has.remove();}
// Firma (drawer con CTA orgánico: cta → slider → verifying → ok)
let SIGN_OPTS=null;
function signHtml(){const o=SIGN_OPTS;if(o)return `<div class="sig-layer" data-sign role="dialog" aria-modal="true" aria-label="${esc(o.title)}"><button class="sig-scrim" data-action="sig-cancel" aria-label="Cancelar firma"></button><section class="sig-sheet"><div class="sig-head"><div><p class="sig-title">${esc(o.title)}</p><p class="sig-sub">${esc(o.sub)}</p></div><button class="sig-close" data-action="sig-cancel" aria-label="Cerrar firma"><span class="bzf-x dark"></span></button></div><div class="sig-body"><div class="sig-hero"><span class="sig-okbadge">${icon('check',22)}</span><strong class="sig-big-t">${esc(o.big)}</strong><span>${esc(o.hero)}</span></div><div class="sig-summary">${o.fields.map(([k,v])=>`<div><small>${esc(k)}</small><span>${esc(v)}</span></div>`).join('')}</div></div><div class="sig-foot"><div class="sig-track" data-phase="cta" role="button" tabindex="0" aria-label="Continuar para firmar"><span class="sig-hint">Desliza para firmar</span><div class="sig-pill"><span class="sig-l sig-l-cta">Continuar para firmar</span><span class="sig-l sig-l-ver">Verificando firma…</span><span class="sig-thumb"><span class="sig-chev">${icon('chevron',20)}</span><span class="sig-spin"></span></span></div><div class="sig-ok"><span>${esc(o.ok)}</span><span class="sig-okc">${icon('check',18)}</span></div></div><button class="sig-cancel" data-action="sig-cancel">Cancelar</button></div></section></div>`;const l=bzfLookup(),nm=bzfName();return `<div class="sig-layer" data-sign role="dialog" aria-modal="true" aria-label="Firmar Bizum"><button class="sig-scrim" data-action="sig-cancel" aria-label="Cancelar firma"></button><section class="sig-sheet"><div class="sig-head"><div><p class="sig-title">Firmar Bizum</p><p class="sig-sub">Pulsa en el botón y desliza para confirmar el envío.</p></div><button class="sig-close" data-action="sig-cancel" aria-label="Cerrar firma"><span class="bzf-x dark"></span></button></div><div class="sig-body"><div class="sig-hero"><span class="sig-okbadge">${icon('check',22)}</span><strong>${fmt(bzfAmt())}</strong><span>Bizum a ${esc(nm||l.formatted)}</span></div><div class="sig-summary"><div><small>Móvil de destino</small><span>${esc(l.formatted)}</span></div><div><small>Concepto</small><span>${esc(bzfConcept())}</span></div></div></div><div class="sig-foot"><div class="sig-track" data-phase="cta" role="button" tabindex="0" aria-label="Continuar para firmar"><span class="sig-hint">Desliza para firmar</span><div class="sig-pill"><span class="sig-l sig-l-cta">Continuar para firmar</span><span class="sig-l sig-l-ver">Verificando firma…</span><span class="sig-thumb"><span class="sig-chev">${icon('chevron',20)}</span><span class="sig-spin"></span></span></div><div class="sig-ok"><span>Bizum firmado</span><span class="sig-okc">${icon('check',18)}</span></div></div><button class="sig-cancel" data-action="sig-cancel">Cancelar</button></div></section></div>`}
function signOpen(opts=null){SIGN_OPTS=opts;const ph=root.querySelector('.phone');if(!ph||ph.querySelector('[data-sign]'))return;ph.insertAdjacentHTML('beforeend',signHtml());SIGN={phase:'cta',drag:0,start:null};const t=ph.querySelector('.sig-track');
 const maxDrag=()=>Math.max(80,t.clientWidth-56);
 const setW=(w,anim)=>{const p=t.querySelector('.sig-pill');p.style.transition=anim?'':'none';p.style.width=w;};
 const phase=ph2=>{SIGN.phase=ph2;t.dataset.phase=ph2;const lay=ph.querySelector('[data-sign]');lay.classList.toggle('locked',ph2==='verifying'||ph2==='ok');t.setAttribute('role',ph2==='cta'?'button':'slider');t.setAttribute('aria-label',{cta:'Continuar para firmar',slider:'Desliza para firmar',verifying:'Verificando firma…',ok:'Bizum firmado'}[ph2]);
  if(ph2==='slider'){setW('48px',true);}
  if(ph2==='verifying'){setW('100%',true);setTimeout(()=>{if(SIGN)phase('ok')},prefersReducedMotion?200:1000);}
  if(ph2==='ok'){lay.classList.add('signed');setTimeout(()=>{if(SIGN){if(SIGN_OPTS){const o=SIGN_OPTS;SIGN=null;SIGN_OPTS=null;const el=root.querySelector('[data-sign]');if(el)el.remove();o.done();}else bzfComplete();}},prefersReducedMotion?300:1150);}};
 const verify=()=>{SIGN.start=null;phase('verifying')};
 t.addEventListener('click',()=>{if(SIGN.phase==='cta')phase('slider');else if(SIGN.phase==='slider'&&!SIGN.dragged)verify();SIGN.dragged=false;});
 t.addEventListener('keydown',e=>{if(!['Enter',' ','ArrowRight'].includes(e.key))return;e.preventDefault();if(SIGN.phase==='cta'&&e.key!=='ArrowRight')phase('slider');else if(SIGN.phase==='slider')verify();});
 t.addEventListener('pointerdown',e=>{if(SIGN.phase!=='slider')return;t.setPointerCapture(e.pointerId);SIGN.start=e.clientX-SIGN.drag;SIGN.dragged=false;});
 t.addEventListener('pointermove',e=>{if(SIGN.phase!=='slider'||SIGN.start===null)return;const m=maxDrag(),x=Math.max(0,Math.min(m,e.clientX-SIGN.start));SIGN.drag=x;if(x>4)SIGN.dragged=true;setW((48+x)+'px',false);t.querySelector('.sig-hint').style.opacity=String(Math.max(0,1-x/m*1.4));if(x>=m*.65)verify();});
 const up=()=>{if(SIGN.phase!=='slider'||SIGN.start===null)return;const m=maxDrag();SIGN.start=null;if(SIGN.drag>=m*.55)verify();else if(SIGN.dragged){SIGN.drag=0;setW('48px',true);t.querySelector('.sig-hint').style.opacity='';}};
 t.addEventListener('pointerup',up);t.addEventListener('pointercancel',up);
 setTimeout(()=>t.focus({preventScroll:true}),320);}
function signClose(){const el=root.querySelector('[data-sign]');SIGN=null;if(!el)return;el.classList.add('closing');setTimeout(()=>el.remove(),prefersReducedMotion?0:240);}
function bzfComplete(){const l=bzfLookup(),a=bzfAmt(),nm=bzfName()||l.formatted;SIGN=null;const ref='BZ-'+String(Date.now()).slice(-6),tm=new Date().toTimeString().slice(0,5);state.bizums=[...(state.bizums||[]),{who:nm,amount:a,concept:bzfConcept(),via:'formulario',phone:l.d,ref,time:tm}];bzf().sent={name:nm,phone:l.formatted,amount:a,concept:bzfConcept(),ref};NEXT_DIR='fade';goto('/operar/bizum/enviado');}
function bzfStart(via='operar'){OPER=false;state.bzf=bzfBlank();state.via=via;state.history=[];goto('/operar/bizum');}
function bzfAct(a){
 if(a==='bzf-start'){bzfStart();return true;}
 if(a==='bzf-start-atajo'){bzfStart('atajo');return true;}
 if(a==='bzf-agenda'){BZF_AGENDA_OPEN=true;bzfAgendaSync();setTimeout(()=>{const i=root.querySelector('[name=bzfSearch]');if(i)i.focus({preventScroll:true})},300);return true;}
 if(a==='bzf-agenda-close'){BZF_AGENDA_OPEN=false;bzfAgendaSync();return true;}
 if(a.startsWith('bzf-pick-')){const c=bzfAgenda().find(x=>x.phone===a.slice(9));if(c){bzf().phone=fmtPhone(c.phone);bzf().name=c.name;}BZF_AGENDA_OPEN=false;render();const i=root.querySelector('#bzf-amount');if(i)i.focus({preventScroll:true});return true;}
 if(a==='bzf-review'){const f=bzf();f.touched=true;const l=bzfLookup();if(l.valid)f.phone=fmtPhone(l.d);if(!bzfOk()){render();const bad=root.querySelector('.bzf-field.has-error input');if(bad)bad.focus({preventScroll:true});return true;}goto('/operar/bizum/revision');return true;}
 if(a==='bzf-edit'){NEXT_DIR='back';goto('/operar/bizum');return true;}
 if(a==='bzf-sign'){if(!bzfOk()){goto('/operar/bizum');return true;}signOpen();return true;}
 if(a==='sig-cancel'){if(SIGN&&(SIGN.phase==='verifying'||SIGN.phase==='ok'))return true;signClose();return true;}
 if(a==='bzf-again'){state.bzf=bzfBlank();NEXT_DIR='fade';goto('/operar/bizum');return true;}
 return false;}
function bzfInput(name,value){const f=bzf();
 if(name==='bzfPhone'){f.phone=value;const l=bzfLookup();if(!l.contact)f.name='';bzfLive();return true;}
 if(name==='bzfAmount'){f.amount=value.replace(/[^\d.,]/g,'');bzfLive();return true;}
 if(name==='bzfConcept'){f.concept=value;return true;}
 if(name==='bzfSearch'){const el=root.querySelector('#bzf-ag-list');if(el)el.innerHTML=bzfAgendaHtml(value);return true;}
 return false;}
