let MV_DOC=false;
function mvAskOpen(){const el=root.querySelector('#mv-ask');if(!el||el.classList.contains('open'))return;el.classList.add('thinking');setTimeout(()=>{el.classList.remove('thinking');el.classList.add('open');},prefersReducedMotion?0:900);}
function mvAskBind(){const sc=root.querySelector('#scroller');if(!sc)return;const chk=()=>{if(sc.scrollTop+sc.clientHeight>=sc.scrollHeight-24)mvAskOpen();};sc.addEventListener('scroll',chk,{passive:true});}
function mvDocSync(){const ph=root.querySelector('.phone');if(!ph)return;const has=ph.querySelector('[data-mvdoc]');if(MV_DOC&&!has)ph.insertAdjacentHTML('beforeend',mvDocHtml());if(!MV_DOC&&has)has.remove();}
function openMove(key){state.moveId=key;state.mvMore=false;state.mvNoteEdit=false;goto(key==='nike'?'/movimientos/nike':String(key).startsWith('card:')?'/movimientos/tarjeta':'/movimientos/bizum');}
function lastBzKey(){const n=(state.bizums||[]).length;return n?'bz:'+(n-1):'bz:seed'}
function mvAct(a){
 if(a==='move-open-bz:last'){openMove(lastBzKey());return true;}
 if(a.startsWith('move-open-cm:')){const [,cid,mid]=a.slice(10).split(':');return cardAct('card-move-'+cid+'-'+mid);}
 if(a.startsWith('move-open-')){openMove(a.slice(10));return true;}
 if(a==='mv-ask-open'){const sc=root.querySelector('#scroller');if(sc)sc.scrollTo({top:sc.scrollHeight,behavior:prefersReducedMotion?'auto':'smooth'});mvAskOpen();return true;}
 if(a==='mv-more'){state.mvMore=!state.mvMore;render();return true;}
 if(a==='mv-note'){if(state.mvNoteEdit){const t=root.querySelector('#mv-note');state.mvNotes={...(state.mvNotes||{}),[state.moveId]:t?t.value.trim():''};state.mvNoteEdit=false;render();}else{state.mvNoteEdit=true;render();const t=root.querySelector('#mv-note');if(t){t.focus();t.setSelectionRange(t.value.length,t.value.length);}}return true;}
 if(a==='mv-doc'){MV_DOC=true;mvDocSync();return true;}
 if(a==='mv-doc-close'){MV_DOC=false;mvDocSync();return true;}
 if(a==='mv-map'){state.toast='Madrid · Nike Store Serrano, calle de Serrano.';render();return true;}
 if(a==='mv-compartir'){if(navigator.share){navigator.share({title:mvData().concept,text:`${mvData().concept} · ${mvData().datetime}`}).catch(()=>{});}else{state.toast='Detalle listo para compartir.';render();}return true;}
 if(a==='mv-fraccionar'||a==='mv-dividir'){state.toast='Esta opción no está disponible en la prueba.';render();return true;}
 if(a==='mv-reportar'){state.toast='Para revisar un pago que no reconoces, pregunta al asistente digital aquí abajo.';render();const s=root.querySelector('#mv-ask');if(s)s.scrollIntoView({behavior:prefersReducedMotion?'auto':'smooth',block:'end'});return true;}
 if(a==='mv-allmoves'){detailOf('card');return true;}
 if(a.startsWith('mv-ask-')){const m=mvData(),c=m.ask.chips[Number(a.slice(7))];if(!c)return true;const q=c[1];journey(guess(q),q,'movimiento');return true;}
 return false;}
