function cardFace(c){const off=cardIsOff(c.id);return `<div class="cv ${off?'is-off':''}" style="--cv-bg:${c.bg};--cv-off:${c.off}" aria-label="Tarjeta ${c.type} terminada en ${c.last}${off?', apagada':''}"><div class="cv-band">${state.blockDone&&c.id==='debito'?'Bloqueada por seguridad':'Apagada'}</div><div class="cv-face"><div class="cv-top"><span class="cv-logo">${SAB_WORD}</span><button class="cv-switch" role="switch" aria-checked="${!off}" aria-label="${off?`Tarjeta ${c.type} apagada. Encender`:`Tarjeta ${c.type} activa. Apagar`}" data-action="card-toggle-${c.id}"><span class="cv-thumb">${off?'<svg width="14" height="14" viewBox="0 0 16 16" fill="none"><rect x="3.2" y="7" width="9.6" height="6.8" rx="1.4" fill="#262626"/><path d="M5.2 7V5.2a2.8 2.8 0 1 1 5.6 0V7" stroke="#262626" stroke-width="1.4" stroke-linecap="round"/></svg>':'<svg width="14" height="14" viewBox="0 0 16 16" fill="none"><rect x="3.2" y="7.2" width="9.6" height="6.6" rx="1.4" stroke="#006DF2" stroke-width="1.4"/><path d="M5.2 7.2V5a2.8 2.8 0 0 1 5.4-.9" stroke="#006DF2" stroke-width="1.4" stroke-linecap="round"/></svg>'}</span></button></div><div class="cv-mid"><div class="cv-type">${c.type} ${VISA_SVG}</div><b>${MV_HOLDER}</b><b>•••• ${c.last}</b></div><button class="cv-data" data-action="card-data">Ver datos</button></div></div>`}
function cardsPage(){const st=cardSt(),c=CARD_DATA[CARD_ORDER[st.idx]]||CARD_DATA.debito,off=cardIsOff(c.id),hid=!state.balanceVisible;
 const q=CARD_Q.trim().toLowerCase();let list=st.tab==='todos'?c.moves:c.moves.filter(m=>Math.abs(m.amount)>50);if(q)list=list.filter(m=>m.concept.toLowerCase().includes(q));
 let prev=null;const rows=list.map(m=>{let h='';if(!q&&m.group!==prev&&!(st.tab==='todos'&&prev===null)){h=`<div class="cm-group">${m.group}</div>`;}prev=m.group;const frac=Math.abs(m.amount)>50;return h+`<button class="cm-row" data-action="card-move-${c.id}-${m.id}"><span class="cm-av" style="background:${m.bg}">${m.letter}</span><span class="cm-main"><span class="cm-top"><span class="cm-name">${esc(m.concept)}</span><span class="cm-amt">${hid?'•••• €':mvMoney(m.amount)}</span></span><span class="cm-sub">${m.date} · ${m.time} h${frac?'<span class="cm-tag">Fraccionar</span>':''}</span></span></button>`}).join('');
 const sp=cardSpent(c);
 return `<header class="backbar mv-bar"><button class="iconbtn" data-action="back" aria-label="Volver">${icon('back')}</button><div class="heading mv-heading">Tarjetas</div><button class="iconbtn" data-action="privacy" aria-label="${state.balanceVisible?'Ocultar':'Mostrar'} importes">${bankGlyph(state.balanceVisible?'eye':'eyeoff')}</button></header>
<main class="main cards-main" id="scroller"><section class="cards-top"><div class="cards-title"><h1>Tarjetas (${CARD_ORDER.length})</h1></div>
<div class="cards-car" id="cards-car">${CARD_ORDER.map(id=>`<div class="cards-slide">${cardFace(CARD_DATA[id])}</div>`).join('')}</div>
<div class="cards-nav"><div class="cards-dots">${CARD_ORDER.map((id,i)=>`<button class="${i===st.idx?'on':''}" data-action="card-go-${i}" aria-label="Ver tarjeta ${CARD_DATA[id].type}"></button>`).join('')}</div><button class="cards-arrow" data-action="card-go-${st.idx-1}" ${st.idx===0?'disabled':''} aria-label="Tarjeta anterior">${icon('back',18)}</button><button class="cards-arrow" data-action="card-go-${st.idx+1}" ${st.idx===CARD_ORDER.length-1?'disabled':''} aria-label="Tarjeta siguiente">${icon('chevron',18)}</button></div>
${off?`<div class="cards-pill warn"><span class="cp-ic">${icon('info',20)}</span><span class="cp-t">${state.blockDone&&c.id==='debito'?'Bloqueada por seguridad. Ya no se pueden hacer pagos con ella.':'Tarjeta apagada. Nadie puede pagar con ella hasta que la enciendas.'}</span></div>`:`<button class="cards-pill" data-action="card-limits"><span class="cp-ic">${QA.configurar[1]}</span><span class="cp-t">Límites de compras y cajero<small>${fmt(st.lim[c.id].pos).replace(',00','')}/mes en compras · ${fmt(st.lim[c.id].atm).replace(',00','')}/día en cajero</small></span><span class="cp-link">Modificar</span></button>`}
<div class="cards-qa">${c.quick.map(k=>`<button class="oper-cell" data-action="card-qa-${k}"><span class="oper-circle">${QA[k][1]}</span><span class="oper-label">${QA[k][0]}</span></button>`).join('')}</div>
<button class="cards-wallet" data-action="card-wallet"><svg width="20" height="22" viewBox="0 0 24 24" fill="#fff" aria-hidden="true"><path d="${CSVG.apple}"/></svg>Añadir a Cartera de Apple</button>
${c.limit?`<div class="cards-credit"><div class="cc-row"><span>Disponible<b>${hid?'•••• €':fmt(c.limit-sp)}</b></span><span class="r">Gastado<em>${hid?'•••• €':fmt(sp)}</em></span></div><div class="cc-bar">${[0,1,2,3,4].map(i=>`<i class="${i<Math.round(sp/c.limit*5)?'on':''}"></i>`).join('')}</div><div class="cc-liq"><span>Liquidación noviembre<small>Se carga el 1 dic en tu Cuenta Online</small></span><span class="cc-tag">En curso</span></div></div>`:`<div class="cards-debit-sum"><span>Gastado este mes</span><b>${hid?'•••• €':fmt(sp)}</b></div>`}
</section>
<section class="cards-moves"><div class="cards-tabs" role="tablist"><button role="tab" aria-selected="${st.tab==='todos'}" data-action="card-tab-todos">Todos</button><button role="tab" aria-selected="${st.tab==='fraccionar'}" data-action="card-tab-fraccionar">Fraccionar</button></div>
<div class="cards-srow"><b>${q?'Resultados':st.tab==='todos'?((list[0]||{}).group||'Hoy'):'Fraccionables'}</b><button class="cards-sbtn" data-action="card-search" aria-label="Buscar movimientos" aria-pressed="${CARD_SEARCH}"><svg viewBox="0 0 20 20" width="20" height="20"><path fill="#006DFF" d="${CSVG.p26c6e700}"/></svg></button></div>
${CARD_SEARCH?`<div class="cards-search"><input name="cardQ" placeholder="Buscar por concepto" value="${esc(CARD_Q)}" autocomplete="off"></div>`:''}
<div id="cards-list">${CARD_LOADING?cardSkeleton():rows||'<p class="cards-empty">No hay movimientos que coincidan.</p>'}</div></section></main>`}
function cardSkeleton(){return [0,1,2,3].map(()=>`<div class="cm-sk"><i class="a"></i><span><i class="b"></i><i class="c"></i></span></div>`).join('')}
function cardsBind(){const car=root.querySelector('#cards-car');if(!car)return;const st=cardSt();const w=()=>car.querySelector('.cards-slide').offsetWidth+8;car.scrollLeft=st.idx*w();let t=null;car.addEventListener('scroll',()=>{clearTimeout(t);t=setTimeout(()=>{const i=Math.round(car.scrollLeft/w());if(i!==cardSt().idx)cardGo(i,true);},90);},{passive:true});if(state.openLimits){state.openLimits=false;setTimeout(()=>limitsOpen(),250);}}
function cardGo(i,fromScroll){const st=cardSt();i=Math.max(0,Math.min(CARD_ORDER.length-1,i));if(i===st.idx&&!fromScroll){return}st.idx=i;CARD_Q='';CARD_LOADING=true;clearTimeout(CARD_LT);CARD_LT=setTimeout(()=>{CARD_LOADING=false;const el=root.querySelector('#cards-list');if(el&&state.screen==='detail'){const car=root.querySelector('#cards-car'),sl=car?car.scrollLeft:0;render();const c2=root.querySelector('#cards-car');if(c2)c2.scrollLeft=sl;}},prefersReducedMotion?0:800);const car=root.querySelector('#cards-car'),sl=car?car.scrollLeft:0;render();const c2=root.querySelector('#cards-car');if(c2){c2.scrollLeft=sl;if(!fromScroll)c2.scrollTo({left:i*(c2.querySelector('.cards-slide').offsetWidth+8),behavior:prefersReducedMotion?'auto':'smooth'});}}
function cardRerender(){const car=root.querySelector('#cards-car'),sl=car?car.scrollLeft:0,sc=root.querySelector('#scroller'),st=sc?sc.scrollTop:0;render();const c2=root.querySelector('#cards-car');if(c2)c2.scrollLeft=sl;const s2=root.querySelector('#scroller');if(s2)s2.scrollTop=st;}
// Face ID reutilizable
function faceVerify(reason,cb){const ph=root.querySelector('.phone');if(!ph)return;ph.insertAdjacentHTML('beforeend',`<div class="face-overlay" data-face><div class="face-card"><div class="face-glyph">${faceGlyph()}</div><h2>Face ID</h2><p>${esc(reason)}</p></div></div>`);const ov=ph.querySelector('[data-face]');setTimeout(()=>{const g=ov.querySelector('.face-glyph');g.classList.add('face-done');g.innerHTML=icon('check',66);ov.querySelector('h2').textContent='Identidad verificada';setTimeout(()=>{ov.remove();cb();},prefersReducedMotion?100:620);},prefersReducedMotion?200:1350);}
// PIN
let PIN_T=null;
function pinOpen(c){const ph=root.querySelector('.phone');if(!ph)return;const pin=c.id==='debito'?'4817':'2093';ph.insertAdjacentHTML('beforeend',`<div class="sig-layer" data-pin role="dialog" aria-modal="true" aria-label="PIN de tu tarjeta"><button class="sig-scrim" data-action="pin-close" aria-label="Cerrar"></button><section class="sig-sheet pin-sheet"><div class="sig-head"><div><p class="sig-title">PIN de tu tarjeta</p><p class="sig-sub">Tarjeta de ${c.type.toLowerCase()} ···· ${c.last}</p></div><button class="sig-close" data-action="pin-close" aria-label="Cerrar"><span class="bzf-x"></span></button></div><div class="pin-digits">${pin.split('').map((d,i)=>`<span style="animation-delay:${i*70}ms">${d}</span>`).join('')}</div><div class="pin-count"><div class="pin-bar"><i></i></div><small>Se ocultará en <b id="pin-s">15</b> s</small></div><div class="pin-foot"><button class="button-secondary" data-action="pin-close">Ocultar PIN</button><button class="bzf-tertiary" data-action="pin-change">Cambiar PIN</button></div></section></div>`);let s=15;clearInterval(PIN_T);PIN_T=setInterval(()=>{s--;const el=root.querySelector('#pin-s');if(el)el.textContent=s;if(s<=0)pinClose();},1000);}
function pinClose(){clearInterval(PIN_T);const el=root.querySelector('[data-pin]');if(!el)return;el.classList.add('closing');setTimeout(()=>el.remove(),prefersReducedMotion?0:240);}
// Límites
let LIM_DRAFT=null,LIM_OPEN=false;
function limitsHtml(){const st=cardSt(),c=CARD_DATA[CARD_ORDER[st.idx]],d=LIM_DRAFT;return `<div class="sig-layer" data-lim role="dialog" aria-modal="true" aria-label="Configurar tarjeta"><button class="sig-scrim" data-action="lim-close" aria-label="Cerrar"></button><section class="sig-sheet lim-sheet"><div class="sig-head"><div><p class="sig-title">Configurar tarjeta</p><p class="sig-sub">Tarjeta de ${c.type.toLowerCase()} ···· ${c.last}</p></div><button class="sig-close" data-action="lim-close" aria-label="Cerrar"><span class="bzf-x"></span></button></div><div class="sig-body">
<div class="lim-card"><div class="lim-h"><span>Compras al mes</span><b id="lim-pos-v">${fmt(d.pos).replace(',00','')}</b></div><input type="range" name="limPos" min="100" max="${c.id==='credito'?3000:5000}" step="100" value="${d.pos}" aria-label="Límite de compras al mes"><div class="lim-scale"><span>100 €</span><span>${c.id==='credito'?'3.000':'5.000'} €</span></div></div>
<div class="lim-card"><div class="lim-h"><span>Retiradas en cajero al día</span><b id="lim-atm-v">${fmt(d.atm).replace(',00','')}</b></div><input type="range" name="limAtm" min="0" max="1000" step="50" value="${d.atm}" aria-label="Límite de cajero al día"><div class="lim-scale"><span>0 €</span><span>1.000 €</span></div></div>
<p class="lim-sec">Permisos</p><div class="lim-card lim-perms">${[['online','Compras por internet','Pagos en webs y apps'],['abroad','Compras en el extranjero','Pagos y cajeros fuera de España']].map(([k,t,s])=>`<label class="lim-perm"><span>${t}<small>${s}</small></span><input type="checkbox" name="lim-${k}" ${d[k]?'checked':''}><i class="lim-sw"></i></label>`).join('')}</div>
<p class="lim-note">Desactivar es al momento. Activar o subir un límite necesita tu firma.</p></div><div class="pin-foot"><button class="button-primary" data-action="lim-save">Guardar cambios</button></div></section></div>`}
function limitsOpen(){const st=cardSt(),id=CARD_ORDER[st.idx];LIM_DRAFT={...st.lim[id]};LIM_OPEN=true;const ph=root.querySelector('.phone');if(!ph||ph.querySelector('[data-lim]'))return;ph.insertAdjacentHTML('beforeend',limitsHtml());}
function limitsClose(){LIM_OPEN=false;const el=root.querySelector('[data-lim]');if(!el)return;el.classList.add('closing');setTimeout(()=>el.remove(),prefersReducedMotion?0:240);}
function limitsSave(){const st=cardSt(),id=CARD_ORDER[st.idx],cur=st.lim[id],d=LIM_DRAFT;const up=d.pos>cur.pos||d.atm>cur.atm||(d.online&&!cur.online)||(d.abroad&&!cur.abroad);const same=JSON.stringify(cur)===JSON.stringify(d);if(same){limitsClose();return;}
 const apply=()=>{st.lim[id]={...d};limitsClose();state.toast=up?'Cambios firmados y aplicados en tu tarjeta.':'Cambios aplicados al momento.';cardRerender();};
 if(!up){apply();return;}
 const c=CARD_DATA[id],f=[];if(d.pos!==cur.pos)f.push(['Compras al mes',fmt(d.pos).replace(',00','')]);if(d.atm!==cur.atm)f.push(['Cajero al día',fmt(d.atm).replace(',00','')]);if(d.online!==cur.online)f.push(['Compras por internet',d.online?'Activadas':'Desactivadas']);if(d.abroad!==cur.abroad)f.push(['Compras en el extranjero',d.abroad?'Activadas':'Desactivadas']);
 limitsClose();setTimeout(()=>signOpen({title:'Firmar cambio de límites',sub:'Pulsa en el botón y desliza para confirmar.',hero:`Tarjeta de ${c.type.toLowerCase()} ···· ${c.last}`,big:'Nuevos límites',fields:f,ok:'Cambios firmados',done:apply}),260);}
function cardAct(a){const st=cardSt(),c=CARD_DATA[CARD_ORDER[st.idx]];
 if(a.startsWith('card-go-')){cardGo(Number(a.slice(8)));return true;}
 if(a.startsWith('card-toggle-')){const id=a.slice(12);if(id==='debito'&&state.blockDone){state.toast='Esta tarjeta está bloqueada por seguridad. Te enviaremos una nueva.';cardRerender();return true;}if(!cardIsOff(id)){st.off[id]=true;state.toast='Tarjeta apagada. Nadie podrá pagar con ella hasta que la enciendas.';cardRerender();}else{faceVerify('Verifica tu identidad para encender la tarjeta',()=>{st.off[id]=false;state.toast='Tarjeta encendida. Ya puedes usarla.';cardRerender();});}return true;}
 if(a==='card-qa-pin'){if(cardIsOff(c.id)){state.toast='Enciende la tarjeta para ver su PIN.';cardRerender();return true;}faceVerify('Verifica tu identidad para ver el PIN',()=>pinOpen(c));return true;}
 if(a==='pin-close'){pinClose();return true;}
 if(a==='pin-change'){pinClose();const q='Quiero cambiar el PIN de mi tarjeta';journey(guess(q),q,'tarjetas');return true;}
 if(a==='card-limits'||a==='card-qa-configurar'){limitsOpen();return true;}
 if(a==='lim-close'){limitsClose();return true;}
 if(a==='lim-save'){limitsSave();return true;}
 if(a.startsWith('card-tab-')){st.tab=a.slice(9);cardRerender();return true;}
 if(a==='card-search'){CARD_SEARCH=!CARD_SEARCH;if(!CARD_SEARCH)CARD_Q='';cardRerender();if(CARD_SEARCH){const i=root.querySelector('[name=cardQ]');if(i)i.focus({preventScroll:true});}return true;}
 if(a.startsWith('card-move-')){const [,,cid,...rest]=a.split('-'),mid=rest.join('-');const m=(CARD_DATA[cid]||{moves:[]}).moves.find(x=>x.id===mid);if(!m)return true;if(m.key==='nike'){openMove('nike');return true;}state.cardMove={...m,cardId:cid};openMove('card:'+cid+':'+mid);return true;}
 if(a==='card-data'){faceVerify('Verifica tu identidad para ver los datos de la tarjeta',()=>{state.toast=`${c.pan.replace(/•+/g,m=>m)} · Caduca 09/29 · CVV oculto`;cardRerender();});return true;}
 if(['card-qa-instant','card-qa-mas','card-qa-formaPago','card-wallet'].includes(a)){state.toast='Esta opción no está disponible en la prueba.';cardRerender();return true;}
 return false;}
function cardInput(name,value,el){if(name==='cardQ'){CARD_Q=value;const st=cardSt();const box=root.querySelector('#cards-list');if(box){const tmp=document.createElement('div');const sc=root.querySelector('#scroller').scrollTop;render();const s2=root.querySelector('#scroller');if(s2)s2.scrollTop=sc;const i=root.querySelector('[name=cardQ]');if(i){i.focus({preventScroll:true});i.setSelectionRange(value.length,value.length);}}return true;}
 if(LIM_DRAFT&&name==='limPos'){LIM_DRAFT.pos=Number(value);const v=root.querySelector('#lim-pos-v');if(v)v.textContent=fmt(LIM_DRAFT.pos).replace(',00','');return true;}
 if(LIM_DRAFT&&name==='limAtm'){LIM_DRAFT.atm=Number(value);const v=root.querySelector('#lim-atm-v');if(v)v.textContent=fmt(LIM_DRAFT.atm).replace(',00','');return true;}
 if(LIM_DRAFT&&(name==='lim-online'||name==='lim-abroad')){LIM_DRAFT[name.slice(4)]=el.checked;return true;}
 return false;}
// V7.16 · Cuentas (réplica de cuentas.tsx del proto original).
const COPY_D="M11.001 13.2197H1.64453V1.63281H11.001V13.2197ZM2.64453 12.2197H10.001V2.63281H2.64453V12.2197ZM8.7793 0V1H1V10.6279H0V0H8.7793Z";
const ACC_DATA={online:{id:'online',name:'Cuenta Online',last:'1048',iban:MV_IBAN,detail:'account'},ahorro:{id:'ahorro',name:'Cuenta Ahorro',last:'3291',iban:'ES12 0081 0216 7300 0103 3291',detail:'savings'}};
const ACC_ORDER=['online','ahorro'];
let ACC_Q='',ACC_SEARCH=false,ACC_LOADING=false,ACC_LT=null,ACC_MORE=false;
let ACC_DOC_INIT=false;
function accSt(){if(!state.acc)state.acc={idx:0,tab:'todos',route:''};if(!ACC_DOC_INIT){ACC_DOC_INIT=true;state.acc.route=ROUTE_PATH;state.acc.idx=state.detail==='savings'?1:0;ACC_LOADING=true;clearTimeout(ACC_LT);ACC_LT=setTimeout(()=>{ACC_LOADING=false;accRerender();},prefersReducedMotion?0:800);}return state.acc}
function accBalance(id){const m=money();return id==='online'?m.online:m.ahorro}
function accMoves(id){if(id==='online')return movesNow().map(t=>({concept:t[0],sub:t[1],amount:t[2],key:t[4],av:t[5]||`<span class="mvl-av" style="background:#e8eef6;color:#334">${icon(t[3],16)}</span>`}));const m=money(),out=[];if(m.covered)out.push({concept:'Traspaso a Cuenta Online',sub:'Hoy · Recibo de la luz',amount:-23,av:`<span class="mvl-av" style="background:#e6f0ff;color:#006dff">${icon('swap',16)}</span>`});out.push({concept:'Traspaso desde Cuenta Online',sub:'1 nov · Ahorro mensual',amount:100,av:`<span class="mvl-av" style="background:#e6f0ff;color:#006dff">${icon('swap',16)}</span>`},{concept:'Intereses',sub:'31 oct · Liquidación mensual',amount:0.72,av:`<span class="mvl-av" style="background:#e8f5ee;color:#008626">${icon('trend',16)}</span>`},{concept:'Traspaso desde Cuenta Online',sub:'1 oct · Ahorro mensual',amount:100,av:`<span class="mvl-av" style="background:#e6f0ff;color:#006dff">${icon('swap',16)}</span>`});return out}
function accUpcoming(id){if(id!=='online')return [{concept:'Traspaso desde Cuenta Online',sub:'Previsto 1 dic · Ahorro mensual',amount:100,av:`<span class="mvl-av" style="background:#e6f0ff;color:#006dff">${icon('swap',16)}</span>`}];const m=money(),r=(c,s,a,l,bg)=>({concept:c,sub:s,amount:a,av:`<span class="mvl-av" style="background:${bg}">${l}</span>`});return [r('Movistar · Fibra y móvil','Previsto 24 nov · Recibo',-m.fibra,'M','#019df4'),r('Iberdrola · Luz','Previsto 26 nov · Recibo',-m.luz,'I','#5fa72e'),r('Nómina · Industrias Gráficas','Previsto 28 nov · Ingreso',m.income,'N','#5a6b80'),r('Mapfre · Seguro del coche','Previsto 29 nov · Recibo',-147.5,'M','#d81e05'),r('Alquiler · Inmobiliaria Sol','Previsto 30 nov · Recibo',-950,'A','#7a5c3e'),r('Liquidación tarjeta crédito ···· 2209','Previsto 1 dic · Tarjeta',-cardSpent(CARD_DATA.credito),'S','#212121')]}
function accCard(a){const hid=!state.balanceVisible,[i,d]=fmt(accBalance(a.id)).replace(' €','').split(',');return `<div class="ac"><p class="ac-name">${a.name}</p><p class="ac-bal">${hid?'•••• €':`${i}<small>,${d}</small><em>€</em>`}</p><button class="ac-iban" data-action="acc-copy-${a.id}" aria-label="Copiar IBAN">${a.iban}<svg viewBox="0 0 11.001 13.2197" width="11" height="13" aria-hidden="true"><path fill="#000" d="${COPY_D}"/></svg></button><button class="ac-more" data-action="acc-detail-${a.id}">Ver detalle</button></div>`}
function accAviso(a){if(a.id!=='online')return '';const v=state.insight;if(v==='warning')return `<div class="acc-aviso"><span class="acc-av-ic warn">${icon('info',18)}</span><div><p>El jueves te pasan la luz (87 €) y te faltan 23 €.</p><button data-action="cover">Cubrirlo desde Ahorro</button></div></div>`;return `<div class="acc-aviso"><span class="acc-av-ic">${icon('mail',18)}</span><div><p>Tu extracto de noviembre de la Cuenta Online ya está disponible.</p><button data-action="alerts">Leer más</button></div></div>`}
function accountsPage(){const st=accSt(),a=ACC_DATA[ACC_ORDER[st.idx]]||ACC_DATA.online,hid=!state.balanceVisible;const base=st.tab==='todos'?accMoves(a.id):accUpcoming(a.id);const q=ACC_Q.trim().toLowerCase();const list=q?base.filter(m=>m.concept.toLowerCase().includes(q)):base;
 let bal=accBalance(a.id);const rows=list.map(m=>{const b=bal;if(st.tab==='todos')bal=Math.round((bal-m.amount)*100)/100;const tag=m.key?'button':'div';return `<${tag} class="cm-row acc-row" ${m.key?`data-action="move-open-${m.key}"`:''}>${m.av}<span class="cm-main"><span class="cm-top"><span class="cm-name">${esc(m.concept)}</span><span class="cm-amt">${hid?'•••• €':mvMoney(m.amount)}</span></span><span class="cm-top cm-sub2"><span class="cm-sub">${esc(m.sub)}</span>${st.tab==='todos'&&!q?`<span class="acc-runbal">${hid?'':fmt(b)}</span>`:''}</span></span></${tag}>`}).join('');
 return `<header class="backbar mv-bar"><button class="iconbtn" data-action="back" aria-label="Volver">${icon('back')}</button><div class="heading mv-heading">Cuentas</div><button class="iconbtn" data-action="privacy" aria-label="${state.balanceVisible?'Ocultar':'Mostrar'} importes">${bankGlyph(state.balanceVisible?'eye':'eyeoff')}</button></header>
<main class="main cards-main" id="scroller"><section class="cards-top acc-top"><div class="cards-title"><h1>Cuentas (${ACC_ORDER.length})</h1><span class="acc-total">${hid?'':`Total ${fmt(money().total)}`}</span></div>
<div class="cards-car acc-car" id="acc-car">${ACC_ORDER.map(id=>`<div class="cards-slide">${accCard(ACC_DATA[id])}</div>`).join('')}</div>
<div class="cards-nav"><div class="cards-dots">${ACC_ORDER.map((id,i)=>`<button class="${i===st.idx?'on':''}" data-action="acc-go-${i}" aria-label="Ver ${ACC_DATA[id].name}"></button>`).join('')}</div><button class="cards-arrow" data-action="acc-go-${st.idx-1}" ${st.idx===0?'disabled':''} aria-label="Cuenta anterior">${icon('back',18)}</button><button class="cards-arrow" data-action="acc-go-${st.idx+1}" ${st.idx===ACC_ORDER.length-1?'disabled':''} aria-label="Cuenta siguiente">${icon('chevron',18)}</button></div>
<div class="cards-qa">${[['bizum','Enviar','Bizum','acc-qa-bizum'],['enviar','Enviar','dinero','journey-transfer'],['sacar','Sacar','dinero','acc-qa-sacar'],['mas','Más','opciones','acc-qa-mas']].map(([i,l1,l2,act])=>`<button class="oper-cell" data-action="${act}"><span class="oper-circle">${i==='mas'?QA.mas[1]:operIcon(i)}</span><span class="oper-label">${l1}<br>${l2}</span></button>`).join('')}</div>
${accAviso(a)}</section>
<section class="cards-moves"><div class="cards-tabs" role="tablist"><button role="tab" aria-selected="${st.tab==='todos'}" data-action="acc-tab-todos">Todos</button><button role="tab" aria-selected="${st.tab==='proximos'}" data-action="acc-tab-proximos">Próximos<i class="acc-badge"></i></button></div>
<div class="cards-srow"><b>${q?'Resultados':st.tab==='todos'?'Últimos movimientos':'Próximos pagos'}</b><button class="cards-sbtn" data-action="acc-search" aria-label="Buscar movimientos" aria-pressed="${ACC_SEARCH}"><svg viewBox="0 0 20 20" width="20" height="20"><path fill="#006DFF" d="${CSVG.p26c6e700}"/></svg></button></div>
${ACC_SEARCH?`<div class="cards-search"><input name="accQ" placeholder="Buscar por concepto" value="${esc(ACC_Q)}" autocomplete="off"></div>`:''}
${st.tab==='proximos'&&a.id==='online'?`<p class="acc-up-note">Hasta el día 30 entran ${fmt(money().income)} y salen ${fmt(money().bills)} en recibos.</p>`:''}
<div id="acc-list">${ACC_LOADING?cardSkeleton():rows||'<p class="cards-empty">No hay movimientos que coincidan.</p>'}</div></section></main>`}
function accRerender(){if(!(state.screen==='detail'&&state.detail!=='card'))return;const car=root.querySelector('#acc-car'),sl=car?car.scrollLeft:0,sc=root.querySelector('#scroller'),t=sc?sc.scrollTop:0;render();const c2=root.querySelector('#acc-car');if(c2)c2.scrollLeft=sl;const s2=root.querySelector('#scroller');if(s2)s2.scrollTop=t;}
function accBind(){const car=root.querySelector('#acc-car');if(!car)return;const st=accSt(),w=()=>car.querySelector('.cards-slide').offsetWidth+8;if(!car.dataset.bound){car.dataset.bound=1;if(Math.abs(car.scrollLeft-st.idx*w())>4)car.scrollLeft=st.idx*w();let t=null;car.addEventListener('scroll',()=>{clearTimeout(t);t=setTimeout(()=>{const i=Math.round(car.scrollLeft/w());if(i!==accSt().idx)accGo(i,true);},90);},{passive:true});}if(ACC_MORE&&!root.querySelector('[data-accmore]'))accMoreOpen(true);}
function accGo(i,fromScroll){const st=accSt();i=Math.max(0,Math.min(ACC_ORDER.length-1,i));if(i===st.idx&&!fromScroll)return;st.idx=i;ACC_Q='';ACC_LOADING=true;clearTimeout(ACC_LT);ACC_LT=setTimeout(()=>{ACC_LOADING=false;accRerender();},prefersReducedMotion?0:800);accRerender();const c2=root.querySelector('#acc-car');if(c2&&!fromScroll)c2.scrollTo({left:i*(c2.querySelector('.cards-slide').offsetWidth+8),behavior:prefersReducedMotion?'auto':'smooth'});}
const ACC_SECTIONS=[['Añadir dinero en cuenta',['Traspasar desde tarjeta Sabadell','Ingresar desde tarjeta de otro banco','Compartir IBAN']],['Impuestos',['Pagar impuestos','Consultar impuestos']],['Recibos y domiciliaciones',['Consultar domiciliaciones','Consultar recibos no domiciliados','Pagar recibos no domiciliados']],['Certificados',['Solicitar nuevo certificado','Consultar certificados']],['Otros',['Trasladar cuenta de otro banco','Buscar movimientos']]];
function accMoreOpen(noAnim){ACC_MORE=true;const ph=root.querySelector('.phone');if(!ph||ph.querySelector('[data-accmore]'))return;ph.insertAdjacentHTML('beforeend',`<div class="mv-doc acc-more ${noAnim?'no-anim':''}" data-accmore role="dialog" aria-modal="true" aria-label="Más opciones"><header class="mv-doc-head"><span class="bar-spacer"></span><strong>Más opciones</strong><button class="iconbtn" data-action="acc-more-close" aria-label="Cerrar"><span class="bzf-x"></span></button></header><div class="acc-more-body">${ACC_SECTIONS.map(([t,ls])=>`<h3>${t}</h3><div class="acc-more-list">${ls.map(l=>`<button data-action="acc-opt-${encodeURIComponent(l)}">${l}${icon('chevron',16)}</button>`).join('')}</div>`).join('')}</div></div>`);}
function accMoreClose(){ACC_MORE=false;const el=root.querySelector('[data-accmore]');if(el)el.remove();}
function accDetailOpen(a){const ph=root.querySelector('.phone');if(!ph)return;ph.insertAdjacentHTML('beforeend',`<div class="sig-layer" data-accdet role="dialog" aria-modal="true" aria-label="Detalle de la cuenta"><button class="sig-scrim" data-action="accdet-close" aria-label="Cerrar"></button><section class="sig-sheet"><div class="sig-head"><div><p class="sig-title">${a.name}</p><p class="sig-sub">Cuenta ···· ${a.last}</p></div><button class="sig-close" data-action="accdet-close" aria-label="Cerrar"><span class="bzf-x"></span></button></div><div class="sig-body"><div class="sig-summary"><div><small>Titular</small><span>${MV_HOLDER}</span></div><div><small>IBAN</small><span>${a.iban}</span></div><div><small>BIC</small><span>BSABESBBXXX</span></div><div><small>Saldo disponible</small><span>${fmt(accBalance(a.id))}</span></div><div><small>${a.id==='online'?'Comisiones':'Remuneración'}</small><span>${a.id==='online'?'0 € de mantenimiento':'0,10 % TAE · intereses mensuales'}</span></div></div></div><div class="pin-foot"><button class="button-secondary" data-action="acc-copy-${a.id}">Copiar IBAN</button></div></section></div>`);}
function accAct(a){const st=accSt(),acc=ACC_DATA[ACC_ORDER[st.idx]];
 if(a.startsWith('acc-go-')){accGo(Number(a.slice(7)));return true;}
 if(a.startsWith('acc-copy-')){const x=ACC_DATA[a.slice(9)];try{navigator.clipboard&&navigator.clipboard.writeText(x.iban.replace(/\s/g,'')).catch(()=>{});}catch(e){}state.toast='IBAN copiado';accRerender();return true;}
 if(a.startsWith('acc-detail-')){accDetailOpen(ACC_DATA[a.slice(11)]);return true;}
 if(a==='accdet-close'){const el=root.querySelector('[data-accdet]');if(el)el.remove();return true;}
 if(a==='acc-qa-bizum'){bzfStart('cuentas');return true;}
 if(a==='acc-qa-sacar'){OPER=true;operarSync();return true;}
 if(a==='acc-qa-mas'){accMoreOpen();return true;}
 if(a==='acc-more-close'){accMoreClose();return true;}
 if(a.startsWith('acc-opt-')){const o=decodeURIComponent(a.slice(8));accMoreClose();if(o==='Compartir IBAN')return accAct('acc-copy-'+acc.id);if(o==='Consultar domiciliaciones'){st.tab='proximos';accRerender();return true;}if(o==='Buscar movimientos'){ACC_SEARCH=true;st.tab='todos';accRerender();const i=root.querySelector('[name=accQ]');if(i)i.focus({preventScroll:true});return true;}state.toast='Esta opción no está disponible en la prueba.';accRerender();return true;}
 if(a.startsWith('acc-tab-')){st.tab=a.slice(8);accRerender();return true;}
 if(a==='acc-search'){ACC_SEARCH=!ACC_SEARCH;if(!ACC_SEARCH)ACC_Q='';accRerender();if(ACC_SEARCH){const i=root.querySelector('[name=accQ]');if(i)i.focus({preventScroll:true});}return true;}
 return false;}
function accInput(value){ACC_Q=value;accRerender();const i=root.querySelector('[name=accQ]');if(i){i.focus({preventScroll:true});i.setSelectionRange(value.length,value.length);}}
const TAB_OF={home:'home',forecast:'home',contract:'contract','contract-detail':'contract'};
function nav(){const cur=TAB_OF[state.screen];const it=([id,t,i])=>`<button class="nav-item" data-action="nav-${id}" ${cur===id?'aria-current="page"':''}><span class="nav-active-line"></span><span class="nav-icon">${bankGlyph(i,cur===id)}</span><span>${t}</span></button>`;return `<nav class="bottomnav" aria-label="Navegación principal">${it(['home','Inicio','home'])}<div class="nav-operar-wrap"><button data-action="nav-operar" aria-label="${OPER?'Cerrar':'Operar'}" aria-expanded="${OPER}" class="nav-operar${OPER?' is-open':''}"><span class="nav-operar-dots" aria-hidden="true">${'<i></i>'.repeat(9)}</span><span class="nav-operar-x" aria-hidden="true"></span></button></div>${it(['contract','Contratar','contract'])}</nav>`}
