const PILLS_DIRECT=params.get('pills')==='directo';
const PILL_TEXT={bizum:'Quiero enviar un Bizum a ',transfer:'Quiero hacer una transferencia a ',balance:'¿Cuánto dinero tengo?',payments:'¿Qué pagos tengo próximamente?'};
