function insightBlock(){const v=state.insight;if(v==='warning')return `<div class="hero-insight warn" aria-live="polite"><p><span class="insight-indicator"></span>El jueves te pasan la luz (87&nbsp;€) y te faltan 23&nbsp;€.</p><div class="insight-action-row"><button class="insight-text-link" data-action="cover">Cubrirlo desde Ahorro ${icon('right',17)}</button></div></div>`;if(v==='fraud')return `<div class="hero-insight danger" aria-live="polite"><p><span class="insight-indicator"></span>Hemos retenido un pago de 349 € en tienda-online.xyz. ¿Lo has hecho tú?</p><div class="insight-action-row"><button class="insight-danger-primary" data-action="fraud-block">No, bloquear tarjeta</button><button class="insight-danger-secondary" data-action="fraud-legit">Sí, he sido yo</button></div></div>`;if(v==='covered')return `<div class="hero-insight" aria-live="polite"><p><span class="insight-indicator"></span>El recibo de la luz ya está cubierto.</p><div class="insight-action-row"><button class="insight-text-link" data-action="nav-money">Ver mis cuentas ${icon('right',17)}</button></div></div>`;if(v==='blocked')return `<div class="hero-insight" aria-live="polite"><p><span class="insight-indicator"></span>Tu tarjeta está bloqueada por seguridad.</p><div class="insight-action-row"><button class="insight-text-link" data-action="nav-products">Ver tarjeta ${icon('right',17)}</button></div></div>`;if(v==='verified')return `<div class="hero-insight" aria-live="polite"><p><span class="insight-indicator"></span>Has confirmado que reconoces el pago.</p></div>`;const lb=(state.bizums||[]).slice(-1)[0];if(lb)return `<div class="hero-insight last-move" aria-live="polite"><p>Tu último movimiento es un Bizum de <button class="move-link" data-action="home-lastmove">${fmt(lb.amount)} a ${esc(lb.who)} <span aria-hidden="true">↗</span></button></p></div>`;return `<div class="hero-insight last-move" aria-live="polite"><p>Tu último movimiento es un pago de <button class="move-link" data-action="home-lastmove">56,99&nbsp;€ en Nike <span aria-hidden="true">↗</span></button> con tu tarjeta *5566</p></div>`}
