function homeQuick(){const q=[['bizum','Enviar Bizum','bzf-start-atajo'],['transfer','Transferencia nacional','journey-transfer'],['sacar','Sacar dinero','oper-na'],['limites','Límites de tarjeta','home-limits']];return `<div class="home-quick">${q.map(([i,t,a])=>`<button class="oper-cell" data-action="${a}"><span class="oper-circle">${i==='transfer'?`<span class="hq-swap">${icon('swap',22)}</span>`:operIcon(i)}</span><span class="oper-label">${t}</span></button>`).join('')}</div>`}
