function home(){const hid=!state.balanceVisible;return `${brand()}<main class="main home-main home-v2" id="scroller"><section class="context-panel"><h1 class="hello">Hola, Laura</h1>${insightBlock()}${homeQuick()}</section><section class="products-panel"><div class="section-head"><h2>Tus productos</h2><button class="textlink" data-action="nav-products">Ver todos ${icon('chevron',15)}</button></div><div class="products-home"><button class="product-tile pt-v2" data-action="detail-account"><div class="pt-top">${thumbAccount()}${icon('chevron',16)}</div><div class="tile-title"><span class="account-dot"></span>Cuentas</div><div class="tile-money ${hid?'hidden-money':''}">${hid?'•••• €':fmt(money().total)}</div><div class="tile-sub">2 cuentas · saldo disponible</div></button><button class="product-tile pt-v2" data-action="detail-card"><div class="pt-top">${thumbCard()}${icon('chevron',16)}</div><div class="tile-title"><span class="account-dot"></span>Tarjetas</div><div class="tile-money ${hid?'hidden-money':''}">${hid?'•••• €':fmt(money().card)}</div><div class="tile-sub">${cardsTileSub()}</div></button></div></section><section class="conversation-panel"><div class="prompt-block"><h2 class="prompt-title">¿Cómo te podemos ayudar?</h2><div class="prompt"><label class="visually-hidden" for="home-prompt">Escribe lo que necesitas</label><textarea id="home-prompt" name="query" placeholder="Pregúntanos o pídenos algo…" rows="2">${esc(state.query)}</textarea><div class="prompt-actions"><div class="prompt-left"><button class="prompt-round" data-action="more-ideas" aria-label="Ver opciones">${icon('plus',19)}</button><button class="prompt-round" data-action="mic" aria-label="Dictado de voz">${icon('mic',19)}</button></div><button class="send" data-action="send-home" aria-label="Enviar mensaje">${icon('send',19)}</button></div></div></div></section></main>${nav()}`}
