function moneyPage(){return `${brand()}<main class="main" id="scroller"><div class="page-content"><h1 class="page-title">Mi dinero</h1><p class="page-subtitle">Tus cuentas y movimientos, de un vistazo.</p><div class="money-overview"><div class="money-kicker">Saldo disponible entre tus cuentas</div><div class="money-total">${state.balanceVisible?fmt(money().total):'•••• €'}</div><div class="money-support">2 cuentas</div><button class="money-link" data-action="journey-balance">Ver desglose ${icon('right',15)}</button></div><div class="action-grid money-actions"><button class="action-card" data-action="bzf-start">${icon('phone',21)}Enviar un Bizum</button><button class="action-card" data-action="journey-transfer">${icon('swap',21)}Hacer transferencia</button></div><div class="section-head" style="margin-top:24px"><h2>Últimos movimientos</h2><button class="textlink" data-action="journey-payments">Próximos pagos ${icon('chevron',14)}</button></div>${movesNow().map(m=>`<${m[4]?`button class="movement movement-btn" data-action="move-open-${m[4]}"`:'div class="movement"'}><div class="movement-icon ${m[5]?'has-av':''}">${m[5]||icon(m[3],17)}</div><div class="movement-name">${m[0]}<small>${m[1]}</small></div><div class="movement-value ${m[2]>0?'positive':''}">${state.balanceVisible?(m[2]>0?'+':'−')+fmt(Math.abs(m[2])):'•••• €'}</div></${m[4]?'button':'div'}>`).join('')}<div class="home-guide"><h3>¿Necesitas entender tus gastos?</h3><p>Puedes preguntar por tus saldos y próximos movimientos sin buscar entre pantallas.</p><button class="helper-link" data-action="journey-spending">¿Puedo gastar 500 € este fin de semana? ${icon('right',14)}</button></div></div></main>${nav()}`}

